public class AVASpecialDiscSalesLine extends common
{




}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
   /// <param name = "_inventTransId">_inventTransId</param>
   /// <param name = "_update">_update</param>
   /// <returns>returns</returns>
   public static AVASpecialDiscSalesLine find(InventTransId            _inventTransId, boolean _update = false)
   {
       AVASpecialDiscSalesLine         specialDiscSalesLine;
       ;

       specialDiscSalesLine.selectForUpdate(_update);

       select firstonly specialDiscSalesLine
           where specialDiscSalesLine.InventTransId == _inventTransId;

       return specialDiscSalesLine;
   }

/// <summary>
/// designed rom AVA
/// </summary>
/// <param name = "_specialDiscSalesOder">_specialDiscSalesOder</param>
public void initFromSpecDiscSalesTable(AVASpecialDiscSalesOrder       _specialDiscSalesOder)
{
    this.SpecialDiscountId4 = _specialDiscSalesOder.SpecialDiscountId4;
    this.SpecialDiscountId5 = _specialDiscSalesOder.SpecialDiscountId5;
    this.SpecialDiscountId6 = _specialDiscSalesOder.SpecialDiscountId6;

    this.SpecialDiscountPct4 = _specialDiscSalesOder.SpecialDiscountPct4;
    this.SpecialDiscountPct5 = _specialDiscSalesOder.SpecialDiscountPct5;
    this.SpecialDiscountPct6 = _specialDiscSalesOder.SpecialDiscountPct6;
}

/// <summary>
///    designed from AVA
/// </summary>
public void initFromSalesParameters()
{
    AVASalesParameters          avaSalesParameters = AVASalesParameters::find();
    this.SpecialDiscountId1 = avaSalesParameters.QuotationSpecialDiscount1;
    this.SpecialDiscountId2 = avaSalesParameters.QuotationSpecialDiscount2;
    this.SpecialDiscountId3 = avaSalesParameters.QuotationSpecialDiscount3;
    this.SpecialDiscountId7 = avaSalesParameters.SocialDiscount;

    this.SpecialDiscountPct1 = 0;
    this.SpecialDiscountPct2 = 0;
    this.SpecialDiscountPct3 = 0;
    this.SpecialDiscountPct7 = 0;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_salesLine">_salesLine</param>
public static void createFromSalesLine(SalesLine    _salesLine)
{
    AVASpecialDiscSalesLine     specialDiscSalesLine;
    specialDiscSalesLine.InventTransId = _salesLine.InventTransId;

    AVASpecialDiscSalesOrder     specialDiscSalesOder = AVASpecialDiscSalesOrder::find(_salesLine.SalesId);

    specialDiscSalesLine.initFromSpecDiscSalesTable(specialDiscSalesOder);
    specialDiscSalesLine.initFromSalesParameters();
    specialDiscSalesLine.insert();
}

/// <summary>
///      designed from AVA
/// </summary>
public void update()
{
    AVASpecialDiscSalesLine         specialDiscSalesLine_orig = this.orig();
    super();
    this.updateSalesLine(specialDiscSalesLine_orig);
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_inventTransIdOrig">_inventTransIdOrig</param>
/// <param name = "_inventTransId">_inventTransId</param>
public static void creatFromOrigSalesLine(InventTransId     _inventTransIdOrig, InventTransId   _inventTransId)
{
    AVASpecialDiscSalesLine     origSpecDiscSalesLine;
    AVASpecialDiscSalesLine     specDiscSalesLine;

    origSpecDiscSalesLine = AVASpecialDiscSalesLine::find(_inventTransIdOrig);
    if (origSpecDiscSalesLine.RecId)
    {
        specDiscSalesLine.data(origSpecDiscSalesLine);
        specDiscSalesLine.InventTransId = _inventTransId;
        specDiscSalesLine.insert();
    }
    else
    {
        AVASpecialDiscSalesLine::createFromSalesLine(SalesLine::findInventTransId(_inventTransId));
    }
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_quotationId">_quotationId</param>
/// <param name = "_salesLine">_salesLine</param>
public static void copyFromQuotationJour(QuotationId   _quotationId, SalesLine   _salesLine)
{
    CustQuotationJour           custQuotationJour;
    AVASpecialDiscSalesLine     specialDiscSalesLine;
    AVASpecialDiscQuotationJour specialDiscQuotationJour;
    AVASpecialDiscSalesOrder    specialDiscSalesOrder;     


    specialDiscSalesLine = AVASpecialDiscSalesLine::find(_salesLine.InventTransId);

    CustQuotationSalesLink    custQuotationSalesLink;

    select firstonly OrigQuotationId, QuotationId from  CustQuotationSalesLink
        order by QuotationDate DESC, QuotationId DESC
            where custQuotationSalesLink.origQuotationId    == _quotationId;

    boolean     noQuotPrice = _salesLine.salesTable().KCS_NoUseQuotPrice;

    select firstonly RecId from  custQuotationJour
        where custQuotationJour.QuotationId == custQuotationSalesLink.quotationId;


    if (custQuotationJour.RecId && !noQuotPrice)
    {
        specialDiscQuotationJour = AVASpecialDiscQuotationJour::findQuotation(custQuotationJour.RecId);
        specialDiscSalesLine.initFromSpecDiscQuotationJour(specialDiscQuotationJour);
    }
    else
    {
        specialDiscSalesLine.initFromSalesParameters();
    }

    if (!specialDiscSalesLine.RecId)
    {
        specialDiscSalesLine.InventTransId = _salesLine.InventTransId;
        specialDiscSalesOrder    = AVASpecialDiscSalesOrder::find(_salesLine.SalesId);
        specialDiscSalesLine.initFromSpecDiscSalesTable(specialDiscSalesOrder);
        specialDiscSalesLine.insert();
    }
    else
    {
        ttsbegin;
        specialDiscSalesLine.selectForUpdate(true);
        specialDiscSalesLine.update();
        ttscommit;
    }
}

/// <summary>
/// desigend from AVA
/// </summary>
/// <param name = "_specialDiscQuotationJour">_specialDiscQuotationJour</param>
public void initFromSpecDiscQuotationJour(AVASpecialDiscQuotationJour       _specialDiscQuotationJour)
{
    this.SpecialDiscountId1 = _specialDiscQuotationJour.SpecialDiscountId1;
    this.SpecialDiscountId2 = _specialDiscQuotationJour.SpecialDiscountId2;
    this.SpecialDiscountId3 = _specialDiscQuotationJour.SpecialDiscountId3;

    this.SpecialDiscountPct1 = _specialDiscQuotationJour.SpecialDiscountPct1;
    this.SpecialDiscountPct2 = _specialDiscQuotationJour.SpecialDiscountPct2;
    this.SpecialDiscountPct3 = _specialDiscQuotationJour.SpecialDiscountPct3;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_specialDiscSalesLine_orig">_specialDiscSalesLine_orig</param>
/// <param name = "_updateFromInsert">_updateFromInsert</param>
protected void updateSalesLine(AVASpecialDiscSalesLine      _specialDiscSalesLine_orig = null, boolean      _updateFromInsert = false)
{
    //AVASpecialDiscSalesLine         specialDiscSalesLine_orig = this.orig();
    SalesLine       salesLine = SalesLine::findInventTransId(this.InventTransId,true);
    if (salesLine.RecId)
    {
        if (_specialDiscSalesLine_orig.SpecialDiscountPct1 != this.SpecialDiscountPct1
     || _specialDiscSalesLine_orig.SpecialDiscountPct2 != this.SpecialDiscountPct2
     || _specialDiscSalesLine_orig.SpecialDiscountPct3 != this.SpecialDiscountPct3
     || _specialDiscSalesLine_orig.SpecialDiscountPct4 != this.SpecialDiscountPct4
     || _specialDiscSalesLine_orig.SpecialDiscountPct5 != this.SpecialDiscountPct5
     || _specialDiscSalesLine_orig.SpecialDiscountPct6 != this.SpecialDiscountPct6
     || _specialDiscSalesLine_orig.SpecialDiscountPct7 != this.SpecialDiscountPct7
     || _updateFromInsert)
        {
            if (salesLine.SalesQty < 0 &&  salesLine.ExpectedRetQty != 0)
            {
                salesLine.LineAmount = salesLine.calcLineAmount(salesLine.ExpectedRetQty);
            }
            else
            {
                salesLine.LineAmount = salesLine.calcLineAmount(salesLine.SalesQty);
            }
            ttsbegin;
            salesLine.doUpdate();
            ttscommit;
        }
    }
}

/// <summary>
/// designed from AVA
/// </summary>
public void insert()
{
    super();
    this.updateSalesLine(null,true);
}

/// <summary>
///    AVA <c>displaySalesPriceRebateIncluded</c> method.
/// </summary>
/// <returns>
///    <c>AVASpecialDiscountSalesPrice</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display AVASpecialDiscountSalesPrice displaySalesPriceRebateIncluded()
{
    SalesPrice  retVal;

    retVal = SalesLine::findInventTransId(this.InventTransId).displayAVASalesPriceRebateIncluded();

    return retVal;
}

/// <summary>
///     AVA <c>resetDiscValues</c> method.
///     AVA - Schneider 23.07.2024
/// </summary>
/// <param name="_inventTransId">
///     <c>InventTransId</c> as type
/// </param>
public static void resetDiscValues(InventTransId _inventTransId)
{
    AVASpecialDiscSalesLine locAVASpecialDiscSalesLine;

    locAVASpecialDiscSalesLine =  AVASpecialDiscSalesLine::find(_inventTransId, true);
    if(locAVASpecialDiscSalesLine.RecId)
    {
        ttsbegin;
        locAVASpecialDiscSalesLine.SpecialDiscountPct1 = 0;
        locAVASpecialDiscSalesLine.SpecialDiscountPct2 = 0;
        locAVASpecialDiscSalesLine.SpecialDiscountPct3 = 0;
        locAVASpecialDiscSalesLine.SpecialDiscountPct5 = 0;
        locAVASpecialDiscSalesLine.SpecialDiscountPct6 = 0;
        locAVASpecialDiscSalesLine.SpecialDiscountPct7 = 0;
        locAVASpecialDiscSalesLine.update();
        ttscommit;
    }
}
